def decrypt_openssl(data, passphrase, key_length=32):
    if data.startswith(b"Salted__"):
        salt = data[len(b"Salted__") : AES.block_size]
        key, iv = evp_bytestokey(passphrase, salt, key_length, AES.block_size)
        d = AES.new(key, AES.MODE_CBC, iv)
        out = d.decrypt(data[AES.block_size :])
        return unpad_pkcs5(out)

def format(cls, formats: _TFormat, params: Mapping[str, str | Callable[[int], str]]) -> str:
    width = term_width()
    static: list[str] = []
    variable: list[tuple[int, Callable[[int], str], int]] = []

    for fmt in formats:
        static.clear()
        variable.clear()
        length = 0
        # Get literal texts, static segments and variable segments from the parsed format
        # and calculate the overall length of the literal texts and static segments after substituting them.
        for literal_text, field_name, format_spec, _conversion in fmt:
            static.append(literal_text)
            length += len(literal_text)
            if field_name is None:
                continue
            if field_name not in params:
                break
            value_or_callable = params[field_name]
            if not callable(value_or_callable):
                static.append(value_or_callable)
                length += len(value_or_callable)
            else:
                variable.append((len(static), value_or_callable, int(format_spec or 0)))
                static.append("")
        else:
            # No variable segments? Just check if the resulting string fits into the size constraints.
            if not variable:
                if length > width:
                    continue
                else:
                    break

            # Get the available space for each variable segment (share space equally and round down).
            max_width = int((width - length) / len(variable))
            # If at least one variable segment doesn't fit, continue with the next format.
            if max_width < 1 or any(max_width < min_width for _, __, min_width in variable):
                continue
            # All variable segments fit, so finally format them, but continue with the next format if there's an error.
            # noinspection PyBroadException
            try:
                for idx, fn, _ in variable:
                    static[idx] = fn(max_width)
            except Exception:
                continue
            break

    return "".join(static)

def _write(self, segment: HLSSegment, result: Response, is_map: bool):
    # TODO: Rewrite HLSSegment, HLSStreamWriter and HLSStreamWorker based on independent initialization section segments,
    #       similar to the DASH implementation
    key = segment.map.key if is_map and segment.map else segment.key
    if key and key.method != "NONE":
        try:
            decryptor = self.create_decryptor(key, segment.num)
        except (StreamError, ValueError) as err:
            log.error(f"Failed to create decryptor: {err}")
            self.close()
            return

        try:
            # Unlike plaintext segments, encrypted segments can't be written to the buffer in small chunks
            # because of the byte padding at the end of the decrypted data, which means that decrypting in
            # smaller chunks is unnecessary if the entire segment needs to be kept in memory anyway, unless
            # we defer the buffer writes by one read call and apply the unpad call only to the last read call.
            encrypted_chunk = result.content
            decrypted_chunk = decryptor.decrypt(encrypted_chunk)
            chunk = unpad(decrypted_chunk, AES.block_size, style="pkcs7")
            self.reader.buffer.write(chunk)
        except (ChunkedEncodingError, ContentDecodingError, ConnectionError) as err:
            log.error(f"Download of segment {segment.num} failed: {err}")
            return
        except ValueError as err:
            log.error(f"Error while decrypting segment {segment.num}: {err}")
            return

    else:
        try:
            for chunk in result.iter_content(self.WRITE_CHUNK_SIZE):
                self.reader.buffer.write(chunk)
        except (ChunkedEncodingError, ContentDecodingError, ConnectionError) as err:
            log.error(f"Download of segment {segment.num} failed: {err}")
            return

    if is_map:
        log.debug(f"Segment initialization {segment.num} complete")
    else:
        log.debug(f"Segment {segment.num} complete")

