                # from within _unsafe_process when from_string is run.
                env = args[0]
                globals = args[2] if len(args) >= 3 else kwargs["globals"]

                # Overwrite the outer render_func
                def render_func(in_str):
                    env.add_extension(SnapshotExtension)
